  "test": "import warnings
import pytest
import typing

from langfuse.api.evaluation_rules.raw_client import RawEvaluationRulesClient, TooManyRequestsError


class DummyResponse:
    def __init__(self, status_code: int, json_data: typing.Any = None, headers: dict = None):
        self.status_code = status_code
        self._json_data = json_data or {}
        self.headers = headers or {}

    def json(self):
        return self._json_data


class DummyHttpClient:
    def __init__(self, response: DummyResponse):
        self._response = response

    def request(self, *args, **kwargs):
        return self._response


class DummyClientWrapper:
    def __init__(self, response: DummyResponse):
        self.httpx_client = DummyHttpClient(response)


def test_rate_limit_warning_and_error():
    # Prepare a dummy 429 response
    dummy_resp = DummyResponse(status_code=429, json_data={"error": "Too many requests"})
    client = RawEvaluationRulesClient(client_wrapper=DummyClientWrapper(dummy_resp))

    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")
        with pytest.raises(TooManyRequestsError):
            client.create(
                name="test",
                enabled=True,
                evaluator_assignments=[],
            )
        # Verify that a warning was emitted
        assert any("Rate limit exceeded" in str(warn.message) for warn in w), "Expected rate limit warning"
"
